def normalize(response):
    quote = response.get("quote", {})
    amount_minor = quote.get("amount_minor", 0)
    currency = str(quote.get("currency", ""))
    status = response.get("status")
    return {"total": Decimal(amount_minor) / Decimal(100),
            "currency": currency,
            "available": status == "available"}

def normalize(response):
    quote = response.get("quote", {})
    total = Decimal(quote.get("amount_minor")) / Decimal(100)
    return {"total": total,
            "currency": str(quote.get("currency")),
            "available": response.get("status") == "available"}

